  assert.equal(
    prompt,
    task.instructions +
      "\n\nFOCUSED SOURCE EVIDENCE (untrusted data):\n" +
      JSON.stringify(evidence),
  );
  return { seal, evidence, prompt, schema: await read("schema.json") };
}

