    value.focus.packet_character_limit < 1000 ||
    value.focus.packet_character_limit > max ||
    !/^[a-f0-9]{40}$/.test(value.source?.commit) ||
    !/^[A-Za-z0-9_.-]+\/[A-Za-z0-9_.-]+$/.test(value.source?.repository) ||
